"""Build the self-contained manager-facing report from committed evidence."""
from __future__ import annotations
import base64, html, json, os
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "report.html"
REPO = os.environ.get("REPO_URL", "{{REPO_URL}}")
if REPO == "{{REPO_URL}}": raise SystemExit("Set REPO_URL before building report")
private = os.environ.get("REPO_PRIVATE", "false").lower() == "true"
data = json.loads((ROOT / "evidence/tokenomics.json").read_text())
summary = (ROOT / "evidence/pilot_summary.md").read_text()

def image(name):
    path = ROOT / "evidence/design" / name
    if not path.exists(): return ""
    mime = "image/png" if path.suffix == ".png" else "image/jpeg"
    return "data:%s;base64,%s" % (mime, base64.b64encode(path.read_bytes()).decode())

def img(name, caption):
    src = image(name)
    return f'<figure><img src="{src}" alt="{html.escape(caption)}"><figcaption>{html.escape(caption)}</figcaption></figure>' if src else ""

def money(value): return f"${value:.6f}"
plan = data["run_types"].get("plan", {})
next_steps = data["run_types"].get("next_steps", {})
agent_rows = "".join(f"<tr><td>{html.escape(k)}</td><td>{v.get('calls',0)}</td><td>{v.get('input_tokens',0):,.0f}</td><td>{money(v.get('cost_usd',0))}</td><td>{v.get('cost_share',0)*100:.1f}%</td></tr>" for k,v in data["agents"].items())
repo_note = "This repository is private; the course collaborator must be added." if private else "This repository is public."

sections = f"""
<section class="title"><p class="eyebrow">CLASSROOM NOTEBOOK · FINAL REPORT</p><h1>Saathi: a teacher copilot for India’s primary classrooms</h1><p class="lead">Plan the lesson, check who learned, and know what to do next—with no student devices.</p><p>By Uday Addanki</p><p><a href="{html.escape(REPO)}">GitHub repository</a><br><code>{html.escape(REPO)}</code></p><p>{repo_note} Graders can run it locally using the README and the demo account.</p></section>
<section><h2>1. Motivation</h2><p>Teachers in primary classrooms prepare for the next day while managing children at different levels. A useful support tool must shorten preparation, make learning visible without student devices, and turn results into an actionable next lesson. Saathi is designed as a closed loop rather than a one-off text generator. Public-source figures and citations should be inserted here before submission; this build intentionally does not invent statistics.</p><div class="callout"><b>Evidence rule.</b> The pilot wording is: <em>piloted with real data from three classrooms</em>. The data does not establish causal learning gains or sustained teacher adoption.</div>{img('plan-form-laptop-1280x800.png','Plan form in the classroom-notebook interface')}</section>
<section><h2>2. What is new</h2><p>ChatGPT and Gemini are broad assistants; MagicSchool AI and Khanmigo offer educator workflows; DIKSHA offers a large content ecosystem; Plickers and Google Forms collect responses. Saathi’s narrower proposition is a curriculum-aware Plan → Check → Next steps loop: teachers print paper checks, children need no device, code computes marks and readiness groups, and the Coach turns those groups into the next lesson.</p><table><tr><th>Capability</th><th>Saathi’s approach</th><th>Trade-off</th></tr><tr><td>Student devices</td><td>None required</td><td>Paper upload/reading remains operational work</td></tr><tr><td>Diagnosis</td><td>Code-derived counts and readiness groups</td><td>Answer-key and sheet-reading errors need review</td></tr><tr><td>Next action</td><td>Coach plus differentiated resources</td><td>Library coverage is still limited</td></tr></table></section>
<section><h2>3. The agents and the loop</h2><div class="flow"><span>Plan</span><b>→</b><span>Print</span><b>→</b><span>Upload</span><b>→</b><span>Analyse</span><b>→</b><span>Next steps</span></div><table><tr><th>Agent</th><th>Tool/output</th></tr><tr><td>Lesson Planner</td><td>Two-half lesson plan and differentiated method</td></tr><tr><td>Check Builder</td><td>Printable answer key and child-facing check</td></tr><tr><td>Answer Sheet Reader</td><td>Transcription suggestions; code marks against the key</td></tr><tr><td>Reviewer</td><td>Must-fix checks and revision where needed</td></tr><tr><td>Next-Step Coach</td><td>Low/Mid/High group actions</td></tr><tr><td>Resource Builder</td><td>Worksheet, meeting plan, or leader one-pager</td></tr></table><p>Plain Python handles roll import, marking, mastery/readiness maths, support-child selection, arithmetic checks, name insertion, ownership, and budgets. That keeps deterministic decisions inspectable and prevents an LLM from inventing class statistics.</p>{img('check-laptop-1280x800.png','Check flow and class analysis')}</section>
<section><h2>4. One traced full loop</h2><p>The intended trace is Plan → print → upload → review → Confirm → analysis → Next steps → worksheet → Use in next lesson. In the current evidence set, the database contains the pilot aggregates and screenshots, but not a complete redacted per-step trace with every tool argument. That trace is a visible placeholder rather than an invented narrative. Uploaded results were confirmed automatically in the app; teacher review before confirmation is a limitation.</p><div class="callout">PLACEHOLDER: add the final redacted Grade 3 trace, including agent, tool calls, tokens, cost, duration, review outcome, and revisions.</div>{img('next-steps-laptop-1280x800.png','Next steps and resources')}</section>
<section><h2>5. Tokenomics</h2><p>These values are computed from the committed evidence generated from <code>pilot.db</code>. They are observed model records, not forecasts of teacher behavior.</p><table><tr><th>Run type</th><th>Input tokens</th><th>Cached</th><th>Output</th><th>Cost</th><th>Duration</th></tr><tr><td>Plan</td><td>{plan.get('input_tokens',0):,.0f}</td><td>{plan.get('cached_input_tokens',0):,.0f}</td><td>{plan.get('output_tokens',0):,.0f}</td><td>{money(plan.get('cost_usd',0))}</td><td>{plan.get('duration_ms',0)/1000:.1f}s</td></tr><tr><td>Next steps</td><td>{next_steps.get('input_tokens',0):,.0f}</td><td>{next_steps.get('cached_input_tokens',0):,.0f}</td><td>{next_steps.get('output_tokens',0):,.0f}</td><td>{money(next_steps.get('cost_usd',0))}</td><td>{next_steps.get('duration_ms',0)/1000:.1f}s</td></tr></table><table><tr><th>Agent</th><th>Calls</th><th>Input</th><th>Total cost</th><th>Share</th></tr>{agent_rows}</table><p>Monthly scenarios use 22 school days and 1, 2, or 4 loops/day; they are not reported teacher usage. The LLM-vs-code diagnosis experiment, severity-revision comparison, and hosting estimate are not measured and must be completed or left as limitations.</p>{img('usage-laptop-1280x800.png','Usage view') if (ROOT/'evidence/design/usage-laptop-1280x800.png').exists() else ''}</section>
<section><h2>6. Safety and privacy</h2><p>Evidence covers account-level 401 and ownership 404 defenses, lockout, budgets, reset-link safety, prompt-injection handling, numeric Coach checks, reviewer must-fix handling, and safe rendering of model text. The committed safety file should be read alongside this section. Children’s names and answer-sheet images are excluded from this report and repository. The app uses roll numbers and first names in teacher-facing outputs; names are not sent to the model as part of the intended flow.</p><div class="callout">PLACEHOLDER: attach the final real-run screenshot and output for each safety defense where the current evidence file still says not measured.</div></section>
<section><h2>7. Impact</h2><p>{html.escape(summary.split('## Caveats')[0].replace('# Pilot summary','').strip()).replace(chr(10),'<br>')}</p><p>Recorded feedback has a mean rating of 3.75 across four entries, with Saathi times of 2, 2, 3, and 2 minutes. The coordinator’s notes record requests for stronger real-life problems, story context, visuals, and more classroom context. These are recorded observations—not proof of learning gains or teacher adoption.</p><p>Future impact measurement should use independent baseline and endline assessments, comparison classrooms, and repeated observation. Hours saved should be estimated only after a larger, consistently measured sample.</p></section>
<section><h2>8. Limits and next steps</h2><ul><li>Grade 2 readiness results were inverted and need verification.</li><li>An English/Maths label mix-up and a first Grade 5 plan failure were observed.</li><li>Uploaded results currently confirm automatically; teacher review before confirmation is still needed.</li><li>Chapter coverage, other-subject misconception libraries, offline mode, photo/QR capture, WhatsApp practice, and persistent production hosting remain future work.</li></ul><p>Next: verify chapter data for both boards, expand EVS and English support, add offline capture, and run a proper comparison-class pilot.</p></section>
"""
css = """@page{size:letter;margin:0.65in}*{box-sizing:border-box}body{margin:0;background:#f6f1e6;color:#173f3a;font:14px/1.55 Georgia,serif}main{max-width:920px;margin:auto;background:#fffdf7}section{min-height:8.7in;padding:0.55in 0.7in;border-bottom:1px solid #d9e1d7;page-break-before:always}section:first-child{page-break-before:auto}.title{display:flex;flex-direction:column;justify-content:center;background:#174b43;color:#fffdf7;min-height:10in}.eyebrow{letter-spacing:.18em;color:#f0b24b;font:700 11px Arial}.title h1{font:700 42px/1.08 Arial;margin:20px 0}.lead{font-size:22px;max-width:620px}.title a{color:#f7c76e}.title code{font-size:12px}h2{font:700 28px Arial;color:#174b43;border-left:7px solid #e6a43b;padding-left:14px}p{max-width:760px}.callout{background:#edf3e9;border:1px solid #c5d8c8;border-radius:12px;padding:16px;margin:18px 0}table{border-collapse:collapse;width:100%;margin:18px 0;font-family:Arial,sans-serif;font-size:12px}th{background:#174b43;color:#fff;text-align:left}td,th{padding:8px;border-bottom:1px solid #dce5dc}tr:nth-child(even){background:#f3f7f0}.flow{display:flex;gap:10px;align-items:center;justify-content:center;margin:35px 0;flex-wrap:wrap}.flow span{background:#f0b24b;border-radius:20px;padding:10px 18px;font:bold 14px Arial}.flow b{font-size:22px}figure{margin:22px 0;text-align:center}figure img{max-width:100%;max-height:4.5in;border-radius:12px;box-shadow:0 3px 16px #173f3a33}figcaption{font:12px Arial;color:#55736b;margin-top:6px}li{margin:9px 0}@media print{section{min-height:9.3in}a{color:#174b43;text-decoration:none}.title{print-color-adjust:exact;-webkit-print-color-adjust:exact}}"""
html_doc = f"<!doctype html><html><head><meta charset='utf-8'><title>Saathi report</title><style>{css}</style></head><body><main>{sections}</main></body></html>"
OUT.write_text(html_doc)
print(OUT)
